def forms(text):
    clean = text.strip()
    return clean.lower(), clean.upper(), clean.title()

def has_digit(text):
    for char in text:
        if char in "0123456789":
            return True
    return False

print(forms("  aDa  "))
print(has_digit("Room 2"))
